-- ItemSparse records from the public Forever 70888 cache and three upstream live-cache records.
-- Cache SHA256: 6a9a36cd8b6c9480ce100ed3705ef8163ee53ec3ebbed227492db1f45ca33edf.
-- https://storage.googleapis.com/raidbots-static/wow/forever/enUS/DBCache.bin
-- https://github.com/advocaite/TrinityCore/tree/7d7c05ef83487b8d292584a0e69a2fd1249a5f59/sql/custom/hotfixes
-- Existing ItemSparse and hotfix records take precedence.
-- Restore missing ItemSparse records from documented Forever live caches, checked against 70888 Item.db2.
CREATE TEMPORARY TABLE forever_item_restore AS SELECT * FROM item_sparse WHERE 1=0;
CREATE TEMPORARY TABLE forever_item_locale_restore AS SELECT * FROM item_sparse_locale WHERE 1=0;
START TRANSACTION;

-- Preserve existing item properties and hotfix records from other migrations.
DELETE s FROM forever_item_restore s
WHERE EXISTS (SELECT 1 FROM item_sparse i WHERE i.ID=s.ID)
   OR EXISTS (SELECT 1 FROM hotfix_data h WHERE h.TableHash=2442913102 AND h.RecordId=s.ID)
   OR EXISTS (SELECT 1 FROM hotfix_data h WHERE h.Id=4000000+s.ID);

SELECT l.* FROM forever_item_locale_restore l JOIN forever_item_restore s ON s.ID=l.ID;
SELECT 4000000+s.ID,s.ID,2442913102,s.ID,1,70888 FROM forever_item_restore s;
COMMIT;
DROP TEMPORARY TABLE forever_item_locale_restore,forever_item_restore;
